WITH lines AS (SELECT id, effective_from, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) li AS tier_value) SELECT CASE WHEN tier_value >= 80 THEN 'PREMIUM' ELSE 'STANDARD' END AS tier_value_tier, currency, APPROX_PERCENTILE(tier_value, 0.9) AS tier_value_p90, SORT_ARRAY(COLLECT_SET(currency)) AS currency_list, COUNT(DISTINCT id) AS distinct_ids, SORT_ARRAY(COLLECT_SET(currency)) AS currency_list_2, RANK() OVER (PARTITION BY CASE WHEN tier_value >= 80 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY COUNT(DISTINCT id) DESC) AS distinct_ids_rank FROM lines GROUP BY tier_value_tier, currency ORDER BY tier_value_tier DESC NULLS FIRST
